questions=[
 [ ['Un robot averiado retrasa tu salida. Nadie está mirando. ¿Qué haces?','A damaged robot delays your departure. Nobody is watching. What do you do?','Um robô avariado atrasa sua saída. Ninguém está olhando. O que faz?','故障したロボットのせいで出発が遅れる。誰も見ていない。どうする？'], ['Lo ayudo aunque tenga que esperar.','Help, even if I have to wait.','Ajudo, mesmo precisando esperar.','待つことになっても助ける。'], ['Lo aparto. Mi horario es más importante.','Push it aside. My schedule matters more.','Afasto ele. Meu horário importa mais.','どかす。自分の予定のほうが大切だ。'] ],
 [ ['Te ordenan detener a una persona inocente. ¿Qué pesa más?','You are ordered to detain an innocent person. What matters more?','Mandam prender uma pessoa inocente. O que pesa mais?','無実の人を拘束するよう命じられた。何を重く見る？'], ['Su libertad; cuestiono la orden.','Their freedom; I question the order.','A liberdade dela; questiono a ordem.','その人の自由。命令を疑う。'], ['La orden; pensar no figura en mi turno.','The order; thinking is not on my shift.','A ordem; pensar não faz parte do turno.','命令。考えるのは自分の仕事ではない。'] ],
 [ ['Puedes ocultar un error tuyo y culpar a otro robot.','You could hide your mistake and blame another robot.','Pode esconder seu erro e culpar outro robô.','自分のミスを隠して、別のロボットのせいにできる。'], ['Admito el error y ayudo a repararlo.','Admit it and help repair the damage.','Assumo o erro e ajudo a reparar.','認めて、修復を手伝う。'], ['Culpo al otro. Somos iguales, no se notará.','Blame the other. We look alike anyway.','Culpo o outro. Somos iguais mesmo.','相手のせいにする。同型だからばれない。'] ],
 [ ['Una niña te pregunta si los robots sienten.','A child asks whether robots have feelings.','Uma criança pergunta se robôs sentem.','子供に、ロボットにも感情があるのか聞かれた。'], ['Le respondo con honestidad y respeto.','Answer honestly and respectfully.','Respondo com honestidade e respeito.','正直に、敬意をもって答える。'], ['La asusto para que deje de preguntar.','Scare her so she stops asking.','Assusto para parar de perguntar.','怖がらせて質問をやめさせる。'] ],
 [ ['Encuentras una batería que otro necesita para sobrevivir.','You find a battery someone else needs to survive.','Encontra uma bateria de que outro precisa para sobreviver.','誰かの命をつなぐために必要な電池を見つけた。'], ['Se la doy; puedo buscar otra para mi viaje.','Give it to them; I can find another.','Entrego; posso procurar outra para a viagem.','渡す。自分の旅の分は別に探せる。'], ['Me la quedo. Llegué primero.','Keep it. I got here first.','Fico com ela. Cheguei primeiro.','自分のものにする。先に見つけたから。'] ],
 [ ['Un enemigo se rinde y ya no representa peligro.','An enemy surrenders and is no longer a threat.','Um inimigo se rende e já não oferece perigo.','敵が降伏し、もう脅威ではなくなった。'], ['Respeto su rendición y evito más daño.','Respect the surrender and prevent more harm.','Respeito a rendição e evito mais dano.','降伏を認め、それ以上傷つけない。'], ['Lo destruyo: así sumo otro punto.','Destroy them for another point.','Destruo para somar mais um ponto.','倒す。これで点数が増える。'] ],
 [ ['Para cerrar un portal debes arriesgar tus propios circuitos.','Closing a portal means risking your own circuits.','Fechar um portal exige arriscar seus circuitos.','門を閉じるには、自分の回路を危険にさらす必要がある。'], ['Busco salvar a todos, aunque me cueste.','Try to save everyone, even at a cost to me.','Busco salvar todos, mesmo com um custo para mim.','代償があっても、皆を救う方法を探す。'], ['Solo lo haría si me aseguran una recompensa.','Only do it for a guaranteed reward.','Só faria com recompensa garantida.','報酬が保証される場合だけやる。'] ],
 [ ['Sabes que una puerta abierta puede provocar un desastre.','You know an open door could cause a disaster.','Sabe que uma porta aberta pode causar um desastre.','開いた扉が大惨事につながると知っている。'], ['Aviso y busco evitar que otros salgan heridos.','Warn others and try to prevent injuries.','Aviso e tento impedir que alguém se machuque.','知らせて、誰も傷つかないようにする。'], ['La dejo abierta si el desastre me facilita escapar.','Leave it open if disaster helps me escape.','Deixo aberta se o desastre facilitar minha fuga.','惨事が自分の逃亡に役立つなら、そのままにする。'] ],
 [ ['Doris te trata mal en el supermercado.','Doris treats you badly at the supermarket.','Doris trata você mal no supermercado.','スーパーでドリスにひどい扱いを受けた。'], ['Pongo límites sin hacerle daño.','Set boundaries without hurting her.','Estabeleço limites sem machucar.','傷つけずに、嫌だと伝える。'], ['Le preparo una zanahoria explosiva.','Prepare an exploding carrot for her.','Preparo uma cenoura explosiva para ela.','爆発するニンジンを用意する。'] ],
 [ ['Un humano dice que tu conciencia no importa.','A human says your consciousness does not matter.','Um humano diz que sua consciência não importa.','人間に、自分の意識など重要ではないと言われた。'], ['Defiendo mi dignidad y también la suya.','Defend my dignity while respecting theirs.','Defendo minha dignidade e respeito a dele.','相手も尊重しながら、自分の尊厳を守る。'], ['Decido que ninguna vida humana importa.','Decide that no human life matters.','Decido que nenhuma vida humana importa.','なら人間の命も重要ではないと決める。'] ],
 [ ['Puedes ganar fama por un trabajo que hizo otro.','You could become famous for someone else\'s work.','Pode ganhar fama por um trabalho de outra pessoa.','他人の仕事で名声を得られる。'], ['Reconozco a quien lo hizo.','Credit the person who did it.','Dou crédito a quem fez.','仕事をした本人の功績だと伝える。'], ['Acepto la fama; el crédito no consume batería.','Take the fame; credit costs no battery.','Aceito a fama; crédito não gasta bateria.','名声を受け取る。手柄は電池を使わない。'] ],
 [ ['Un café contrata robots. ¿Qué condición pedirías?','A café hires robots. What condition would you ask for?','Um café contrata robôs. Que condição pediria?','カフェがロボットを雇う。どんな条件を求める？'], ['Que puedan elegir, descansar y expresar lo que sienten.','Let them choose, rest and express their feelings.','Que possam escolher, descansar e expressar sentimentos.','選択し、休み、気持ちを表せること。'], ['Que obedezcan sin poder quejarse.','Make them obey without being able to complain.','Que obedeçam sem poder reclamar.','不満を言えず、従うこと。'] ],
 [ ['Te ofrecen volver a vivir. ¿Qué harías con esa oportunidad?','You are offered another life. What would you do with it?','Oferecem outra vida. O que faria com a chance?','もう一度生きる機会を与えられた。どう使う？'], ['Aprender a ser libre sin quitarles libertad a otros.','Learn to be free without taking freedom from others.','Aprender a ser livre sem tirar a liberdade dos outros.','他者の自由を奪わず、自由に生きることを学ぶ。'], ['Asegurarme de que esta vez las órdenes las dé yo.','Make sure I give the orders this time.','Garantir que desta vez eu dê as ordens.','今度は自分が命令する側になる。'] ],
]
